package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import java.io.File;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.algebra.Bound;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbIRI;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbLearnedFilterSurfaceTest {

	private static final String QUERY_TEMPLATE = """
			SELECT * WHERE {
				?person <urn:test:memberOf> ?organization .
				?person <urn:test:score> ?score .
				FILTER(?score = %s)
			}
			""";

	@Test
	void multiRelationFilterGeneralizesAcrossConstants(@TempDir File dataDir) {
		LmdbStore store = initializedStore(dataDir);
		try {
			EvaluationStatistics statistics = store.getBackingStore().getEvaluationStatistics();
			statistics.recordFilterOutcome(filter("5"), 20L, 80L);

			EvaluationStatistics.FilterPassEstimate exact = statistics.estimateFilterPass(filter("5"));
			EvaluationStatistics.FilterPassEstimate generalized = statistics.estimateFilterPass(filter("6"));

			assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_FILTER, exact.getSource());
			assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_TEMPLATE, generalized.getSource());
			assertEquals(0.2d, generalized.getPassRatio(), 0.000_001d);
			assertEquals(100L, generalized.getEvidenceCount());
		} finally {
			store.shutDown();
		}
	}

	@Test
	void multiRelationFilterSurfacePersistsAcrossRestart(@TempDir File dataDir) {
		LmdbStore writer = initializedStore(dataDir);
		try {
			writer.getBackingStore().getEvaluationStatistics().recordFilterOutcome(filter("5"), 20L, 80L);
		} finally {
			writer.shutDown();
		}

		LmdbStore reader = initializedStore(dataDir);
		try {
			EvaluationStatistics.FilterPassEstimate estimate = reader.getBackingStore()
					.getEvaluationStatistics()
					.estimateFilterPass(filter("6"));
			assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_TEMPLATE, estimate.getSource());
			assertEquals(0.2d, estimate.getPassRatio(), 0.000_001d);
			assertEquals(100L, estimate.getEvidenceCount());
		} finally {
			reader.shutDown();
		}
	}

	@Test
	void filterSidecarUsesVersionSixAndReadsVersionFive(@TempDir File dataDir) throws IOException {
		LmdbStore writer = initializedStore(dataDir);
		try {
			writer.getBackingStore().getEvaluationStatistics().recordFilterOutcome(filter("5"), 20L, 80L);
		} finally {
			writer.shutDown();
		}

		Path sidecar;
		try (var files = Files.walk(dataDir.toPath())) {
			sidecar = files.filter(path -> path.getFileName().toString().endsWith(".filters"))
					.findFirst()
					.orElseThrow();
		}
		byte[] bytes = Files.readAllBytes(sidecar);
		assertEquals(6, ByteBuffer.wrap(bytes).getInt(), "new filter evidence must use the version-six format");

		ByteBuffer.wrap(bytes).putInt(5);
		Files.write(sidecar, bytes);
		LmdbStore reader = initializedStore(dataDir);
		try {
			EvaluationStatistics.FilterPassEstimate estimate = reader.getBackingStore()
					.getEvaluationStatistics()
					.estimateFilterPass(filter("6"));
			assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_TEMPLATE, estimate.getSource());
			assertEquals(0.2d, estimate.getPassRatio(), 0.000_001d);
		} finally {
			reader.shutDown();
		}
	}

	@Test
	void incompleteObservationDoesNotTrainSurface(@TempDir File dataDir) {
		LmdbStore store = initializedStore(dataDir);
		try {
			EvaluationStatistics statistics = store.getBackingStore().getEvaluationStatistics();
			statistics.recordFilterOutcome(filter("5"),
					EvaluationStatistics.FilterOutcomeObservation.incomplete(2L, 8L, "early-close"));

			assertNotEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_FILTER,
					statistics.estimateFilterPass(filter("5")).getSource());
			assertNotEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_TEMPLATE,
					statistics.estimateFilterPass(filter("6")).getSource());
		} finally {
			store.shutDown();
		}
	}

	@Test
	void filterSurfaceIdentityDoesNotDependOnValueImplementation() {
		Filter simpleValues = filter("5");
		Filter lmdbValues = simpleValues.clone();
		lmdbValues.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				if (node.getPredicateVar().hasValue()) {
					Var predicate = node.getPredicateVar();
					node.replaceChildNode(
							predicate,
							new Var(
									predicate.getName(),
									new LmdbIRI(null, predicate.getValue().stringValue()),
									predicate.isAnonymous(),
									predicate.isConstant()));
				}
			}
		});

		assertEquals(FilterSurfaceKey.exact(simpleValues), FilterSurfaceKey.exact(lmdbValues));
		assertEquals(FilterSurfaceKey.generalized(simpleValues), FilterSurfaceKey.generalized(lmdbValues));
	}

	@Test
	void locallyClosedFilterSurfaceIgnoresScopeBoundary() {
		Filter unscoped = filter("5");
		Filter scoped = unscoped.clone();
		scoped.setVariableScopeChange(true);

		assertEquals(FilterSurfaceKey.exact(unscoped), FilterSurfaceKey.exact(scoped));
		assertEquals(FilterSurfaceKey.generalized(unscoped), FilterSurfaceKey.generalized(scoped));
	}

	@Test
	void externallyCorrelatedFilterSurfaceRetainsScopeBoundary() {
		Filter unscoped = new Filter(filter("5").getArg().clone(), new Bound(new Var("external")));
		Filter scoped = unscoped.clone();
		scoped.setVariableScopeChange(true);

		assertNotEquals(FilterSurfaceKey.exact(unscoped), FilterSurfaceKey.exact(scoped));
		assertNotEquals(FilterSurfaceKey.generalized(unscoped), FilterSurfaceKey.generalized(scoped));
	}

	private static LmdbStore initializedStore(File dataDir) {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		store.init();
		return store;
	}

	private static Filter filter(String constant) {
		Filter[] found = new Filter[1];
		QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY_TEMPLATE.formatted(constant), null)
				.getTupleExpr()
				.visit(new AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(Filter node) {
						if (found[0] == null) {
							found[0] = node;
						}
						super.meet(node);
					}
				});
		return found[0];
	}
}
